"""Data-quality scorecard for customers.csv.

Each rule yields a violation count; violation rate = count / total rows.
Overall score = max(0, 100 - sum(weight_i * rate_i * 100)).
"""
import csv
import json
import re
from datetime import datetime

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
VALID_PLANS = {"free", "pro", "team"}

RULES = {
    "duplicate_id":     {"weight": 3},
    "malformed_email":  {"weight": 2},
    "bad_date":         {"weight": 2},
    "age_out_of_range": {"weight": 1},
    "blank_country":    {"weight": 1},
    "invalid_plan":     {"weight": 1},
}


def load_rows(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def check_duplicate_id(rows):
    counts = {}
    for r in rows:
        counts[r["id"]] = counts.get(r["id"], 0) + 1
    return sum(c - 1 for c in counts.values() if c > 1)


def check_malformed_email(rows):
    return sum(1 for r in rows if not EMAIL_RE.match(r["email"] or ""))


def check_bad_date(rows):
    bad = 0
    for r in rows:
        try:
            datetime.strptime(r["signup_date"], "%Y-%m-%d")
        except (ValueError, TypeError):
            bad += 1
    return bad


def check_age_out_of_range(rows):
    bad = 0
    for r in rows:
        try:
            age = int(r["age"])
        except (ValueError, TypeError):
            bad += 1
            continue
        if not 13 <= age <= 110:
            bad += 1
    return bad


def check_blank_country(rows):
    return sum(1 for r in rows if not (r["country"] or "").strip())


def check_invalid_plan(rows):
    return sum(1 for r in rows if r["plan"] not in VALID_PLANS)


CHECKS = {
    "duplicate_id": check_duplicate_id,
    "malformed_email": check_malformed_email,
    "bad_date": check_bad_date,
    "age_out_of_range": check_age_out_of_range,
    "blank_country": check_blank_country,
    "invalid_plan": check_invalid_plan,
}


def build_scorecard(path):
    rows = load_rows(path)
    total = len(rows)
    results = []
    penalties = []
    for rule, check in CHECKS.items():
        violations = check(rows)
        rate = violations / total if total else 0.0
        weight = RULES[rule]["weight"]
        penalty = weight * rate * 100
        penalties.append(penalty)
        results.append({
            "rule": rule,
            "violations": violations,
            "violation_rate": round(rate, 6),
            "weight": weight,
            "penalty": round(penalty, 4),
        })
    score = max(0.0, round(100.0 - sum(penalties), 4))
    return {
        "file": path,
        "total_rows": total,
        "rules": results,
        "overall_score": score,
    }


def main(path="customers.csv"):
    card = build_scorecard(path)
    with open("scorecard.json", "w") as f:
        json.dump(card, f, indent=2)
    print(f"Scorecard written to scorecard.json — overall score: {card['overall_score']}")
    return card


if __name__ == "__main__":
    main()

